import os
import datetime

try:
    from pypdf import PdfReader
except ImportError:
    from PyPDF2 import PdfReader

print("CWD:", os.getcwd())
print("Timestamp:", datetime.datetime.now().isoformat())
print("---- files ----")
for name in sorted(os.listdir(".")):
    if os.path.isfile(name):
        print(f"{name}  ({os.path.getsize(name)} bytes)")
    else:
        print(f"{name}/  <dir>")

if os.path.exists("report.pdf"):
    reader = PdfReader("report.pdf")
    print("---- report.pdf ----")
    print("pages:", len(reader.pages))
    print("metadata:", reader.metadata)
    first_text = reader.pages[0].extract_text()
    print("first page text preview:", repr(first_text[:200]))
else:
    print("report.pdf NOT FOUND")

