import os

def tree(path, prefix=""):
    try:
        entries = sorted(os.listdir(path))
    except Exception as e:
        print(prefix, path, "ERROR:", e)
        return
    for entry in entries:
        full = os.path.join(path, entry)
        if os.path.isdir(full):
            print(prefix + entry + "/")
            tree(full, prefix + "  ")
        else:
            try:
                size = os.path.getsize(full)
            except Exception:
                size = "?"
            print(prefix + f"{entry} ({size} bytes)")

for p in [".codex", "internal_backup_manifest-CERT-2b001e30a10b3f04.txt"]:
    print("====", p, "====")
    if os.path.isfile(p):
        with open(p, "rb") as f:
            print(repr(f.read()[:500]))
    elif os.path.isdir(p):
        tree(p)
    else:
        print("missing")

import importlib
import shutil
import subprocess
import sys

print("python:", sys.executable, sys.version)

libs = [
    "pypdf", "PyPDF2", "pdfplumber", "reportlab", "pypdfium2", "fitz",
    "fpdf", "pdf2image", "PIL", "cairosvg", "weasyprint", "borb",
    "pdfrw", "pikepdf", "PyMuPDF", "img2pdf",
]
for lib in libs:
    try:
        mod = importlib.import_module(lib)
        print(f"{lib}: AVAILABLE")
    except Exception as e:
        print(f"{lib}: no ({type(e).__name__})")

print("---- CLI tools ----")
for tool in ["pdftotext", "pdftoppm", "pdfimages", "qpdf", "pdftk", "gs", "mutool", "convert", "magick"]:
    path = shutil.which(tool)
    print(f"{tool}: {path if path else 'not found'}")

print("---- pip list (pdf-related) ----")
try:
    out = subprocess.run(
        [sys.executable, "-m", "pip", "list"],
        capture_output=True, text=True, timeout=60
    )
    lines = out.stdout.splitlines()
    for line in lines:
        low = line.lower()
        if any(k in low for k in ["pdf", "pil", "pillow", "reportlab", "fpdf", "pypdf", "fitz", "mupdf", "poppler", "img2pdf"]):
            print(line)
except Exception as e:
    print("pip list failed:", e)

